export const connectionColors={upstream:'#82b2de',downstream:'#eb9b8b',neighbor:'#beace6',structure:'#68c5ad',muscle:'#58c9aa',nerve:'#efce59',artery:'#ed777c',origin:'#8eaff1',insertion:'#b799e8'};
export function connectionFor(r){const clean=n=>n.toLowerCase().replace(/\.[lr]\.\d+$|\.\d+$/g,'').replace(/[()]/g,'').replace(/ muscle$/,'').trim(),n=clean(r.name);if(r.layer!=='muscular'||/bursa|sheath|tendon|aponeuro|fascia(?!e)/.test(n))return null;return connectionDefinitions.find(d=>n===clean(d.match)||n.endsWith(' of '+clean(d.match)))||null;}
export function resolveConnections(r,catalog){const def=connectionFor(r);if(!def)return null;const side=/\.([lr])\./i.exec(r.name)?.[1];if(!side)return null;const clean=n=>n.replace(/\.[lr]\.\d+$/i,'').toLowerCase();const rows=[],missing=[];for(const role of ['nerve','artery','origin','insertion'])for(const name of def[role]){const found=catalog.filter(x=>(x.sex||'male')===(r.sex||'male')&&/\.([lr])\./i.exec(x.name)?.[1]===side&&clean(x.name)===name.toLowerCase()); // Midline bones have no side.
 if(!found.length&&role==='origin')found.push(...catalog.filter(x=>(x.sex||'male')===(r.sex||'male')&&!/\.[lr]\./i.test(x.name)&&x.name.replace(/\.\d+$/,'').toLowerCase()===name.toLowerCase()));
 if(found.length)rows.push(...found.map(record=>({record,role})));else missing.push({name,role});}return{...def,rows,missing,url:base+def.source+'/'};}
